const input = $json.body || {};
const escapeHtml = (value) => String(value || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').split(String.fromCharCode(34)).join('&quot;').replace(/'/g, '&#39;');
const email = String(input.email || '').trim().toLowerCase();
const fullName = escapeHtml(input.full_name);
const username = escapeHtml(input.username);
if (!email || !email.includes('@')) throw new Error('A valid account email is required');
const signInUrl = 'https://n8n-project-dev-2rd4r7.eastus.cloudapp.azure.com/login';
const html = `<!doctype html><html><body style='margin:0;padding:0;background:#f2f5fa;font-family:Arial,sans-serif;color:#10233f;'><table role='presentation' width='100%' cellspacing='0' cellpadding='0' style='background:#f2f5fa;padding:32px 16px;'><tr><td align='center'><table role='presentation' width='100%' cellspacing='0' cellpadding='0' style='max-width:640px;background:#ffffff;border:1px solid #dbe4f0;border-radius:18px;overflow:hidden;box-shadow:0 12px 32px rgba(15,39,77,.10);'><tr><td style='padding:28px 32px;background:#153b82;color:#ffffff;'><div style='font-size:12px;font-weight:700;letter-spacing:2px;color:#9edff0;margin-bottom:8px;'>MASAR IT SUPPORT</div><h1 style='margin:0;font-size:28px;line-height:1.25;'>Welcome to Masar</h1></td></tr><tr><td style='padding:32px;'><p style='margin:0 0 18px;font-size:17px;line-height:1.7;'>Hello <strong>${fullName}</strong>,</p><p style='margin:0 0 22px;color:#53657d;font-size:15px;line-height:1.7;'>Your Masar IT Support account has been created successfully. You can now create support tickets, follow their progress, and receive important status notifications.</p><table role='presentation' width='100%' cellspacing='0' cellpadding='0' style='margin:0 0 24px;background:#f7f9fc;border:1px solid #e1e8f2;border-radius:12px;'><tr><td style='padding:18px 20px;'><div style='font-size:12px;font-weight:700;text-transform:uppercase;letter-spacing:1px;color:#718096;margin-bottom:8px;'>Account details</div><div style='font-size:14px;line-height:1.8;'><strong>Username:</strong> ${username}<br><strong>Email:</strong> ${escapeHtml(email)}</div></td></tr></table><table role='presentation' cellspacing='0' cellpadding='0'><tr><td style='border-radius:10px;background:#eef2f7;border:1px solid #d7dee8;'><a href='${signInUrl}' style='display:inline-block;padding:13px 22px;color:#243b5a;text-decoration:none;font-size:15px;font-weight:700;'>Sign in to Masar</a></td></tr></table><p style='margin:26px 0 0;padding-top:20px;border-top:1px solid #e4eaf2;color:#718096;font-size:13px;line-height:1.6;'>For your security, Masar will never ask you to send your password by email.</p></td></tr><tr><td style='padding:18px 32px;background:#f7f9fc;color:#8190a5;font-size:12px;text-align:center;'>Masar IT Support · Automated account notification</td></tr></table></td></tr></table></body></html>`;
return [{json:{email,subject:'Welcome to Masar IT Support',html}}];
